void __thiscall CHARACTER::SetSkillNextReadTime(CHARACTER *this,DWORD dwVnum,time_t time)

{
  if (this->m_pSkillLevels != (TPlayerSkill *)0x0) {
    this->m_pSkillLevels[dwVnum].tNextRead = time;
  }
  return;
}
